import ctypes, os, platform, struct, sys
NUM = {"kill": 62, "tkill": 200, "tgkill": 234}
ERR = {"ESRCH": 3, "EPERM": 1}
def insn(code, jt, jf, k): return struct.pack("HBBI", code, jt, jf, k)
if len(sys.argv) < 4 or sys.argv[2] != "--" or platform.machine() != "x86_64": sys.exit(2)
rules = []
for item in sys.argv[1].split(","):
    name, err, pid = item.split(":")
    rules.append((NUM[name], ERR[err], int(pid)))
prog = [insn(0x20, 0, 0, 4), insn(0x15, 1, 0, 0xC000003E), insn(0x06, 0, 0, 0x80000000)]
for nr, err, pid in rules:
    prog += [insn(0x20, 0, 0, 0), insn(0x15, 0, 3, nr), insn(0x20, 0, 0, 16), insn(0x15, 0, 1, pid), insn(0x06, 0, 0, 0x00050000 | err)]
prog.append(insn(0x06, 0, 0, 0x7FFF0000))
blob = b"".join(prog)
buf = ctypes.create_string_buffer(blob, len(blob))
fprog = struct.pack("HxxxxxxP", len(prog), ctypes.addressof(buf))
libc = ctypes.CDLL(None, use_errno=True)
libc.prctl.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong]
if libc.prctl(38, 1, 0, 0, 0) != 0: raise OSError(ctypes.get_errno(), "NO_NEW_PRIVS")
holder = ctypes.create_string_buffer(fprog, len(fprog))
if libc.prctl(22, 2, ctypes.addressof(holder), 0, 0) != 0: raise OSError(ctypes.get_errno(), "SECCOMP")
os.execv(sys.argv[3], sys.argv[3:])

