exec 2>/dev/null

P=$PWD
/usr/bin/mkfifo "$P/gate"; exec 9<> "$P/gate"
nap() { read -t "${1:-0.05}" -u 9 _junk; }
for n in alpha alphax xalpha beta longnamedprocess1234567890 py chr; do :; done
for n in alpha alphax xalpha beta longnamedprocess1234567890; do /usr/bin/ln -s /usr/bin/sleep "$P/g1$n"; done
for n in py chr; do /usr/bin/ln -s /usr/bin/python3 "$P/g1$n"; done
declare -A PID
PID[sh]=$$
wait_comm() { local tag=$1 want=$2 c i; for ((i=0;i<400;i++)); do c=; read -r c < "/proc/${PID[$tag]}/comm" 2>/dev/null; [[ $c == "${want:0:15}" ]] && return 0; nap 0.005; done; return 1; }
mk() { local tag=$1 name=$2; shift 2; "$P/$name" "${@:-60}" & PID[$tag]=$!; wait_comm "$tag" "$name"; }
mks() { local tag=$1 name=$2; shift 2; /usr/bin/setsid "$P/$name" "${@:-60}" & PID[$tag]=$!; wait_comm "$tag" "$name"; }
mkg() { local tag=$1 name=$2; shift 2; /usr/bin/python3 -c 'import os,sys; os.setpgid(0,0); os.execv(sys.argv[1], sys.argv[1:])' "$P/$name" "${@:-60}" & PID[$tag]=$!; wait_comm "$tag" "$name"; }
mkpy() { local tag=$1; shift; "$P/g1py" -c 'import time; time.sleep(60)' "$@" & PID[$tag]=$!; wait_comm "$tag" g1py; }
alive() { local t out=; for t in "$@"; do if kill -0 "${PID[$t]}" 2>/dev/null; then out+=" $t=alive"; else out+=" $t=dead"; fi; done; echo "state:$out"; }
reap() { local t; for t in "${!PID[@]}"; do [[ $t == sh ]] && continue; kill -KILL "${PID[$t]}" 2>/dev/null; wait "${PID[$t]}" 2>/dev/null; done; }
trap 'reap; /usr/bin/rm -f "$P/o" "$P/e"' EXIT
mapsed() { local t s=; for t in "${!PID[@]}"; do s+="s/(^|[^0-9])${PID[$t]}(\$|[^0-9])/\\1<$t>\\2/g;"; done; /usr/bin/sed -E "$s"; }
norm() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //; s/^(pgrep|pidof): //'; }
# run CMD...: status, then stdout with PIDs mapped to fixture tags (control characters made visible), then stderr
run() { "$@" >"$P/o" 2>"$P/e"; local rc=$?; echo "rc=$rc"; mapsed <"$P/o" | /usr/bin/cat -A | /usr/bin/sed 's/^/out:/'; norm <"$P/e" | /usr/bin/sed 's/^/err:/'; }
# runf CMD...: like run but only fixture lines are kept (all other processes in the VM are ignored)
runf() { "$@" >"$P/o" 2>"$P/e"; local rc=$?; echo "rc=$rc"; mapsed <"$P/o" | /usr/bin/grep -E '^<[a-z0-9]+>' | /usr/bin/grep -v '^<sh>' | /usr/bin/cat -A | /usr/bin/sed 's/^/out:/'; }
# shape CMD...: status, whether stdout/stderr are empty (text of diagnostics is deliberately not compared)
shape() { "$@" >"$P/o" 2>"$P/e"; local rc=$?; local o=empty e=empty; [[ -s $P/o ]] && o=text; [[ -s $P/e ]] && e=text; echo "rc=$rc stdout=$o stderr=$e"; }
t() { echo "== $*" | mapsed; run pgrep "$@"; }
tf() { echo "== $*" | mapsed; runf pgrep "$@"; }
ts() { echo "== $*" | mapsed; shape pgrep "$@"; }

norm() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //; s/^(killall|pkill|pgrep): //'; }
settle() { local i t any; for ((i=0;i<40;i++)); do any=0; for t in "$@"; do kill -0 "${PID[$t]}" 2>/dev/null && any=1; done; ((any)) || return 0; nap 0.05; done; }
INJ=$P/inject.py
# inj PID CMD...: run a shell command string with kill(PID) failing with ESRCH inside the filtered process
inj() { local pid=$1; shift; /usr/bin/python3 "$INJ" "kill:ESRCH:$pid" -- "$BASH" --noprofile --norc -c "$*"; }
runq() { "$@" >"$P/o" 2>"$P/e"; local rc=$?; local e=empty; [[ -s $P/e ]] && e=text; echo "rc=$rc stderr=$e"; mapsed <"$P/o" | /usr/bin/cat -A | /usr/bin/sed 's/^/out:/'; }
mkq() { local tag=$1 name=$2; shift 2; "$P/$name" "${@:-60}" & PID[$tag]=$!; }

echo "proc-visible-in-private-root=$([[ -e /proc/self ]] && echo yes || echo no)"
killall g1alpha >/dev/null 2>&1; echo "no-proc rc=$?"
killall >/dev/null 2>&1; echo "usage rc=$?"

